// Generate today's date in YYYY-MM-DD format (Cairo timezone)
const today = new Date();
const cairoOffset = 2; // EET+2 (adjust to 3 during DST if needed)
const cairoTime = new Date(today.getTime() + cairoOffset * 3600 * 1000);
const dateStr = cairoTime.toISOString().split('T')[0];
return { today: dateStr };

// ─── BUILD AI REPORT PROMPT ────────────────────────────────────────────
// Aggregates today's Price_Log and Price_Index into structured data
// to feed the Groq AI for report generation.

const today        = $('Set Today Date').item.json.today;
const priceLog     = $('Read Today Price_Log').all().map(i => i.json);
const priceIndex   = $('Read Today Price_Index').all().map(i => i.json);

// Aggregate OOS items
const oosOurs = priceLog.filter(r =>
  (r.Is_Ours === 'TRUE' || r.Is_Ours === true) && (r.In_Stock === 'FALSE' || r.In_Stock === false)
);
const oosCompetitor = priceLog.filter(r =>
  (r.Is_Ours === 'FALSE' || r.Is_Ours === false) && (r.In_Stock === 'FALSE' || r.In_Stock === false)
);

// Platform coverage
const byPlatform = {};
priceLog.forEach(r => {
  if (!byPlatform[r.Platform]) byPlatform[r.Platform] = { total: 0, inStock: 0, outOfStock: 0 };
  byPlatform[r.Platform].total++;
  if (r.In_Stock === 'TRUE' || r.In_Stock === true) byPlatform[r.Platform].inStock++;
  else byPlatform[r.Platform].outOfStock++;
});

// Price index summary — join our SKUs vs competitors in same category
const ourPrices = {};
const compPrices = {};
priceIndex.forEach(r => {
  const key = `${r.Category}__${r.SKU}`;
  if (r.Is_Ours === 'TRUE' || r.Is_Ours === true) {
    ourPrices[r.Category] = ourPrices[r.Category] || [];
    ourPrices[r.Category].push({ sku: r.SKU, price: parseFloat(r.Price_EGP), platform: r.Platform });
  } else {
    compPrices[r.Category] = compPrices[r.Category] || [];
    compPrices[r.Category].push({ sku: r.SKU, price: parseFloat(r.Price_EGP), platform: r.Platform });
  }
});

// Build price gap analysis per category
const priceGaps = [];
Object.keys(ourPrices).forEach(cat => {
  const ourAvg = ourPrices[cat].reduce((s, p) => s + p.price, 0) / ourPrices[cat].length;
  const compItems = compPrices[cat] || [];
  const compAvg  = compItems.length ? compItems.reduce((s, p) => s + p.price, 0) / compItems.length : null;
  if (compAvg !== null) {
    const index = Math.round((compAvg / ourAvg) * 100);
    priceGaps.push({
      category : cat,
      our_avg_price   : Math.round(ourAvg * 100) / 100,
      comp_avg_price  : Math.round(compAvg * 100) / 100,
      price_index     : index,
      interpretation  : index > 110 ? 'We are cheaper than competitors' :
                        index < 90  ? 'We are more expensive than competitors' :
                        'Price parity with competitors'
    });
  }
});

const reportData = {
  date           : today,
  total_scraped  : priceLog.length,
  platform_summary: byPlatform,
  our_oos_count  : oosOurs.length,
  our_oos_items  : oosOurs.map(r => ({ sku: r.Matched_SKU, platform: r.Platform, category: r.Category, first_oos: r.First_Seen_OOS })),
  competitor_oos_count : oosCompetitor.length,
  competitor_oos_items : oosCompetitor.map(r => ({ product: r.Raw_Product_Name, platform: r.Platform, category: r.Category })),
  price_gap_analysis: priceGaps
};

return { reportData: JSON.stringify(reportData, null, 2), today };

